    "sg9-7-ex-q": "<style>\n  .q-card { background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 138, 101, 0.35); border-radius: 12px; padding: 16px; margin-bottom: 24px; box-shadow: 0 4px 15px rgba(0,0,0,0.25); }\n  .q-title { font-size: 17.5px; font-weight: 700; color: #FF8A65; margin-bottom: 10px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n  .q-text { font-size: 15.5px; color: #FFFFFF; line-height: 1.9; margin-bottom: 12px; font-weight: 500; }\n  .sub-q { font-size: 15px; font-weight: 600; margin: 12px 0 4px; line-height: 1.8; }\n  .sol-box { background: rgba(0, 0, 0, 0.32); border-left: 3.5px solid #FF8A65; border-radius: 8px; padding: 14px 16px; margin-top: 12px; }\n  .sol-title { font-size: 14.5px; font-weight: 700; color: #FFCCBC; margin-bottom: 8px; }\n  .sol-step { font-size: 15px; color: #E2E8F0; line-height: 1.9; }\n  .sol-step div { margin-top: 5px; margin-bottom: 5px; }\n  .lbl { color: #FFCCBC; font-weight: 700; }\n  .hl { color: #FF8A65; font-weight: 700; }\n  .rev { text-align: justify; }\n  .pt { text-align: left !important; padding-left: 16px; text-indent: -16px; }\n  .pt::before { content: \"•\"; color: #FF8A65; font-weight: 700; display: inline-block; width: 16px; text-indent: 0; }\n  .sec { color: #FF8A65; font-weight: 700; font-size: 15.5px; margin-top: 14px !important; text-align: left !important; }\n  .ans-box { background: rgba(76, 175, 80, 0.15); border: 1.5px solid #4CAF50; border-radius: 8px; padding: 8px 14px; margin-top: 12px; line-height: 1.8; text-align: left; }\n  .ans-label { color: #A5D6A7; font-weight: 700; font-size: 14px; }\n  .ans-val { color: #FFFFFF; font-weight: 700; font-size: 15px; }\n  .exam { background: rgba(255, 138, 101, 0.10); border: 1.5px dashed #FF8A65; border-radius: 8px; padding: 10px 12px; margin: 12px 0 4px; color: #FFFFFF; text-align: left; line-height: 1.8; }\n  .exam-t { color: #FF8A65; font-weight: 700; font-size: 14.5px; display: block; margin-bottom: 2px; }\n  .diagram-card { background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 138, 101, 0.4); border-radius: 10px; padding: 10px; margin: 14px 0; text-align: center; }\n  .diagram-wrapper { display: block; background: #1E1E2E; border-radius: 8px; padding: 4px; margin: 0 auto; width: 100%; box-sizing: border-box; overflow: hidden; }\n  .diagram-wrapper svg { display: block; width: 100%; height: auto; max-width: 100%; margin: 0 auto; }\n  .diagram-caption { color: #CBD5E1; font-size: 13.5px; text-align: center; margin-top: 8px; font-weight: 500; }\n  .badge { display: inline-block; background: rgba(255, 138, 101, 0.18); border: 1px solid #FF8A65; color: #FFCCBC; border-radius: 6px; padding: 0 8px; font-size: 12.5px; font-weight: 700; }\n  .tbl-wrap { width: 100%; overflow-x: auto; margin: 8px 0; }\n  .dt { width: 100%; border-collapse: collapse; font-size: 13px; }\n  .dt th, .dt td { border: 1px solid rgba(255, 255, 255, 0.2); padding: 6px 5px; color: #FFFFFF; line-height: 1.45; text-align: left; vertical-align: top; }\n  .dt th { background: rgba(255, 138, 101, 0.2); color: #FFCCBC; }\n  .q-card .q-text, .q-card .sub-q { color: #FF8A65 !important; text-align: justify !important; }\n  .q-card .sol-step > div.rev { text-align: justify !important; }\n  .q-card .sol-step > div.pt, .q-card .sol-step > div.sec { text-align: left !important; }\n</style>\n<div style=\"padding: 4px 2px;\">\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q1.</div>\n    <div class=\"q-text\">Explain the major physical divisions of Jammu, Kashmir and Ladakh?</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\"><span class=\"lbl\">The Outer Plains:</span> alluvial plains of the Chenab, Tawi and Ravi (Anderwah and Bajwat); 110 km from the Ravi to the Chenab; 330–360 m; cut by ravines (Khads).</div><div class=\"pt\"><span class=\"lbl\">The Shiwaliks:</span> youngest mountains; 20–50 km wide, 600–1,220 m; duns like Basohli, Ramkote, Dansal, Udhampur, Sunderbani.</div><div class=\"pt\"><span class=\"lbl\">The Middle Himalayas (Pir Panjal):</span> 1,800–3,600 m; “Pahar”; from the Ravi to the Poonch; 10–60 km wide; Trikuta mountain and Patnitop.</div><div class=\"pt\"><span class=\"lbl\">The Valley of Kashmir:</span> between the Greater and Middle Himalayas; 40–60 km wide, 130–140 km long, 1,500–1,800 m; valley floor, Karewas and side valleys.</div><div class=\"pt\"><span class=\"lbl\">The Ladakh Region:</span> northernmost arid tableland at about 5,000 m; cold desert; Zanskar, Ladakh and Karakoram ranges, Aksai Chin, Gilgit and Baltistan.</div></div></div>\n  </div>\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q2.</div>\n    <div class=\"q-text\">Name the areas of Jammu Division which are covered by the alluvial plains?</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\"><b>Kathua, Akhnoor, Hiranagar, Bishnah, R.S. Pura</b> and <b>Domana</b>, and parts of Jammu city — <b>Talab Tillo, Gandhi Nagar</b> and <b>Satwari</b>.</div></div></div>\n  </div>\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q3.</div>\n    <div class=\"q-text\">Discuss the main features of climate of Ladakh.</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\">Very cold and very dry — a <b>cold desert</b> (Arctic type).</div><div class=\"pt\">Great extremes of heat and cold with excessive dryness.</div><div class=\"pt\">Little precipitation throughout the year, mainly as <b>snow</b>.</div><div class=\"pt\">Great difference between temperatures in the <b>sun and the shade</b>.</div><div class=\"pt\"><b>Short summers</b> and <b>long, extremely cold winters</b>.</div></div></div>\n  </div>\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q4.</div>\n    <div class=\"q-text\">Name the main tributaries of River Jhelum?</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\"><b>Romushi, Doodh Ganga, Sukhnag, Lidder, Sindh Nallah, Madhumati</b> and <b>Phuru</b>.</div></div></div>\n  </div>\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q5.</div>\n    <div class=\"q-text\">Which mountain ranges of Himalayas surround the valley of Kashmir?</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\">The <b>Greater Himalayas</b> in the north and the <b>Middle Himalayas (Pir Panjal)</b> in the south.</div></div></div>\n  </div>\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q6.</div>\n    <div class=\"q-text\">Name the main rivers and tributaries which flow through the outer plains of Jammu?</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\"><span class=\"lbl\">Rivers:</span> <b>Chenab, Tawi</b> and <b>Ravi</b>.</div><div class=\"pt\"><span class=\"lbl\">Tributaries/streams:</span> <b>Basantar, Ujh, Tawi</b> and <b>Manawar Tawi</b>.</div></div></div>\n  </div>\n  <div class=\"q-card\">\n    <div class=\"q-title\">Q7.</div>\n    <div class=\"q-text\">Give a brief account of the soils found in Jammu, Kashmir and Ladakh.</div>\n    <div class=\"sol-box\"><div class=\"sol-title\">Answer:</div><div class=\"sol-step\"><div class=\"pt\"><span class=\"lbl\">Alluvial soil (Jammu plains):</span> old alluvium (Bhangar) above river banks, free from floods; new alluvium (Khaddar) in flood plains, often inundated.</div><div class=\"pt\"><span class=\"lbl\">Karewa soil (Kashmir; Kishtwar, Bhaderwah):</span> lacustrine deposits; coarse near the Jhelum flanks, finer in the centre; with irrigation, very productive for apple, almond and saffron.</div><div class=\"pt\"><span class=\"lbl\">Ladakh:</span> no well-developed soil profile (cold desert); alluvial tracts along the Sindh (Indus) and its tributaries; mostly mountainous soils.</div><div class=\"pt\">Brown forest soils and mountain soils are also found in different regions.</div></div></div>\n  </div>\n</div>",
